<script lang="ts">
 import {onMount,untrack} from 'svelte';import {calendarDays,dateKey,validateEvent,type CalendarEvent} from './logic';import {allRecords,writeRecords} from '../../local-db';import CopyButton from '../../components/CopyButton.svelte';import type {ToolState} from '../../types';
 let {state:data=$bindable()}: {state:ToolState} = $props();untrack(()=>{data.date??=dateKey(new Date());data.view??='month';data.events??=[];data.loaded??=false;data.error??='';data.draft??={id:'',title:'',start:data.date+'T09:00',end:data.date+'T10:00'};});
 let busy=$state(false);let days=$derived(calendarDays(data.date,data.view));
 onMount(()=>{if(data.loaded)return;allRecords<CalendarEvent>('events').then(events=>{if(events.length>2000)throw new Error('予定が2,000件を超えています。');data.events=events.map(validateEvent);data.loaded=true;}).catch(e=>data.error=`読み込み失敗: ${e.message}`);});
 function navigate(delta:number){const date=new Date(data.date+'T12:00:00');if(data.view==='week')date.setDate(date.getDate()+delta*7);else{date.setDate(1);date.setMonth(date.getMonth()+delta);}const key=dateKey(date);selectDate(key);}
 function selectDate(key:string){try{calendarDays(key,data.view);data.date=key;data.error='';}catch(e){data.error=(e as Error).message;}}
 function draft(key=data.date){data.draft={id:'',title:'',start:key+'T09:00',end:key+'T10:00'};}
 function eventsFor(day:string){return (data.events as CalendarEvent[]).filter(e=>e.start<=day+'T23:59'&&e.end>day+'T00:00').sort((a,b)=>a.start.localeCompare(b.start));}
 async function save(){busy=true;try{const event=validateEvent({...data.draft,id:data.draft.id||crypto.randomUUID()});if(!data.draft.id&&data.events.length>=2000)throw new Error('予定は最大2,000件です。');await writeRecords('events',[event]);data.events=[...data.events.filter((e:CalendarEvent)=>e.id!==event.id),event];data.draft={...event};data.error='';}catch(e){data.error=(e as Error).message;}finally{busy=false;}}
 async function remove(){if(!data.draft.id||!confirm('この予定を削除しますか？'))return;busy=true;try{await writeRecords('events',[],[data.draft.id]);data.events=data.events.filter((e:CalendarEvent)=>e.id!==data.draft.id);draft();data.error='';}catch(e){data.error=(e as Error).message;}finally{busy=false;}}
</script>
{#if data.error}<p role="alert" class="error">{data.error}</p>{/if}
<div class="action-row"><button onclick={()=>navigate(-1)} aria-label="前の期間">←</button><label>表示する日<input type="date" value={data.date} min="1900-01-01" max="2100-12-31" onchange={e=>selectDate(e.currentTarget.value)}/></label><button onclick={()=>navigate(1)} aria-label="次の期間">→</button><button onclick={()=>selectDate(dateKey(new Date()))}>今日</button><label>表示<select bind:value={data.view}><option value="month">月</option><option value="week">週</option></select></label></div>
{#if data.loaded}<div class="calendar-scroll"><div class="calendar-grid" role="table" aria-label="予定一覧"><div class="calendar-weekdays" role="row">{#each ['月','火','水','木','金','土','日'] as day}<div role="columnheader">{day}</div>{/each}</div>{#each Array(data.view==='month'?6:1) as _,week}<div role="row" class="calendar-row">{#each days.slice(week*7,week*7+7) as day}<div role="cell" class="calendar-day" class:today={day===dateKey(new Date())}><button class="day-label" onclick={()=>{selectDate(day);draft(day);}} aria-label={`${day}に予定を作成`}>{day.slice(5)}</button>{#each eventsFor(day) as event}<button class="calendar-event" onclick={()=>{data.draft={...event};}}>{event.start.slice(11)} {event.title}</button>{/each}</div>{/each}</div>{/each}</div></div>
<div class="field-heading"><span>{data.draft.id?'予定を編集':'予定を登録'}</span><button onclick={()=>draft()}>新規予定</button></div>
<label>予定名<input bind:value={data.draft.title} maxlength="200"/></label><div class="form-grid"><label>開始日時<input type="datetime-local" bind:value={data.draft.start} min="1900-01-01T00:00" max="2100-12-31T23:59"/></label><label>終了日時<input type="datetime-local" bind:value={data.draft.end} min="1900-01-01T00:00" max="2100-12-31T23:59"/></label></div>
<div class="action-row"><button class="primary" onclick={save} disabled={busy}>予定を保存</button><button onclick={remove} disabled={busy||!data.draft.id}>予定を削除</button><CopyButton text={(data.events as CalendarEvent[]).map(e=>`${e.start} 〜 ${e.end}\t${e.title}`).join('\n')} label="全予定をコピー"/></div>{:else}<p class="tool-note">端末内の予定を読み込み中。保存領域を利用できない場合はブラウザ設定を確認してください。</p>{/if}
<p class="tool-note">端末内のIndexedDBに保存。1900〜2100年・最大2,000件。日時は端末のローカル壁時計で保持し、時差変換・繰り返し・通知・他タブ同期はありません。</p>
